def recolor(m):
    raw=m.group()[1:]
    if len(raw) not in (3,6):return m.group()
    if len(raw)==3:raw=''.join(c*2 for c in raw)
    rgb=[int(raw[i:i+2],16)/255 for i in (0,2,4)]
    h,l,sat=colorsys.rgb_to_hls(*rgb)
    if 30<h*360<175:
        rgb=colorsys.hls_to_rgb(213/360,l,min(sat,.6))
        return '#'+''.join(f'{round(c*255):02x}' for c in rgb)
    return m.group()
s=re.sub(r'#[0-9a-fA-F]{3,8}\b',recolor,s)
